// AccordionWithAlign.js
import React from 'react';
import { settings, Icon } from 'carbon-components-react';
import { Accordion as CarbonAccordion, AccordionItem as CarbonAccordionItem } from 'carbon-components-react';
import cx from 'classnames';
const { prefix } = settings;

export function Accordion({ align = 'end', children, className, ...rest }) {
  // propagate align into each AccordionItem
  const items = React.Children.map(children, child =>
    React.isValidElement(child)
      ? React.cloneElement(child, { align })
      : child
  );
  return (
    <CarbonAccordion className={className} {...rest}>
      {items}
    </CarbonAccordion>
  );
}

export function AccordionItem({
  align = 'end',
  title,
  children,
  className,
  ...rest
}) {
  // conditional class to move arrow to start
  const headingClass = cx(
    `${prefix}--accordion__heading`,
    {
      // this modifier switches flex-direction and spacing
      [`${prefix}--accordion__heading--start`]: align === 'start',
    }
  );

  return (
    <CarbonAccordionItem className={className} {...rest}>
      <div className={headingClass}>
        <Icon
          name="chevron--down"
          className={`${prefix}--accordion__arrow`}
        />
        <button className={`${prefix}--accordion__button`}>
          {title}
        </button>
      </div>
      <div className={`${prefix}--accordion__content`}>{children}</div>
    </CarbonAccordionItem>
  );
}

// App.js
import React from 'react';
import ReactDOM from 'react-dom';
import { Accordion, AccordionItem } from './AccordionWithAlign';
import './styles.css';

function App() {
  return (
    <div style={{ padding: '2rem', background: '#161616', color: '#fff' }}>
      <h3>Accordion with align="start"</h3>
      <Accordion align="start">
        <AccordionItem title="Section 1 title">
          <p>
            Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do
            eiusmod tempor incididunt ut labore et dolore magna aliqua.
          </p>
        </AccordionItem>
        <AccordionItem title="Section 2 title">
          <p>Content for section 2</p>
        </AccordionItem>
      </Accordion>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

// styles.css
/* default Carbon styles are loaded via its CSS import elsewhere */

/* modifier to flip arrow and title order */
.bx--accordion__heading--start {
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
}

.bx--accordion__heading--start .bx--accordion__arrow {
  margin-right: 1rem;
  margin-left: 0;
}
